'use server';

import { z } from 'zod';
import { revalidatePath } from 'next/cache';

const BookingSchema = z.object({
  packageId: z.string().uuid(),
  travelerCount: z.coerce.number().min(1).max(20),
  travelDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Invalid date format'),
  customerEmail: z.string().email(),
});

export type BookingFormState = {
  status: 'idle' | 'success' | 'error';
  errors?: Record<string, string[]>;
  message?: string;
};

export async function submitBookingAction(
  prevState: BookingFormState,
  formData: FormData
): Promise<BookingFormState> {
  // 1. Session verification layer
  // const session = await getAuthSession();
  // if (!session) return { status: 'error', message: 'Unauthorized' };

  // 2. Parse and validate FormData with Zod
  const rawData = Object.fromEntries(formData.entries());
  const validatedFields = BookingSchema.safeParse(rawData);

  if (!validatedFields.success) {
    return {
      status: 'error',
      errors: validatedFields.error.flatten().fieldErrors,
      message: 'Validation failed. Please verify form inputs.',
    };
  }

  try {
    // 3. Perform internal DB mutation (Drizzle / Prisma / Supabase)
    const { packageId, travelerCount, travelDate, customerEmail } = validatedFields.data;

    // Simulated DB write: await db.insert(bookings).values({ ... });

    // 4. Invalidate relevant server cache boundaries
    revalidatePath(`/tours/${packageId}`);

    return {
      status: 'success',
      message: 'Booking confirmed successfully!',
    };
  } catch (error) {
    return {
      status: 'error',
      message: 'Database mutation failed. Our engineering team has been alerted.',
    };
  }
}

'use client';

import { useActionState } from 'react';
import { submitBookingAction, BookingFormState } from '@/actions/booking-actions';

const initialState: BookingFormState = {
  status: 'idle',
};

export function BookingForm({ packageId }: { packageId: string }) {
  const [state, formAction, isPending] = useActionState(submitBookingAction, initialState);

  return (
    <form action={formAction} className="space-y-4 max-w-lg">
      <input type="hidden" name="packageId" value={packageId} />

      <div>
        <label htmlFor="travelDate" className="block text-sm font-medium">Travel Date</label>
        <input 
          id="travelDate"
          type="date" 
          name="travelDate" 
          required 
          className="w-full border p-2 rounded"
        />
        {state.errors?.travelDate && (
          <p className="text-red-500 text-xs mt-1">{state.errors.travelDate[0]}</p>
        )}
      </div>

      <div>
        <label htmlFor="travelerCount" className="block text-sm font-medium">Passengers</label>
        <input 
          id="travelerCount"
          type="number" 
          name="travelerCount" 
          defaultValue={1} 
          min={1} 
          className="w-full border p-2 rounded"
        />
      </div>

      <div>
        <label htmlFor="customerEmail" className="block text-sm font-medium">Email</label>
        <input 
          id="customerEmail"
          type="email" 
          name="customerEmail" 
          required 
          className="w-full border p-2 rounded"
        />
        {state.errors?.customerEmail && (
          <p className="text-red-500 text-xs mt-1">{state.errors.customerEmail[0]}</p>
        )}
      </div>

      <button 
        type="submit" 
        disabled={isPending}
        className="bg-blue-600 text-white px-4 py-2 rounded font-medium disabled:opacity-50"
      >
        {isPending ? 'Reserving Seats...' : 'Confirm Reservation'}
      </button>

      {state.message && (
        <p className={`text-sm ${state.status === 'success' ? 'text-green-600' : 'text-red-600'}`}>
          {state.message}
        </p>
      )}
    </form>
  );
}
